import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || "http://localhost:32501/api/auth";

// Handle errors centrally
const handleError = (error) => {
  if (error.response) {
    console.error(`Error: ${error.response.status} - ${error.response.data.message || error.message}`);
    throw new Error(error.response.data.message || 'Server error occurred');
  } else if (error.request) {
    console.error('No response received', error.request);
    throw new Error('No response received from server');
  } else {
    console.error('Error setting up request', error.message);
    throw new Error(error.message);
  }
};

// Function to register a user
export const register = async (userData) => {
  try {
    const response = await axios.post(`${API_URL}/register`, userData, {
      headers: {
        'Content-Type': 'application/json',
      },
      withCredentials: true,
    });
    return response.data;
  } catch (error) {
    handleError(error);
  }
};

// Function to login
export const login = async (credentials) => {
  try {
    const response = await axios.post(`${API_URL}/login`, credentials, {
      headers: {
        'Content-Type': 'application/json',
      },
      withCredentials: true,
    });

    console.log("Credentials sent: ", credentials); // Log credentials to check
    return response.data;
  } catch (error) {
    handleError(error);
  }
};

// Function to send a password reset email
export const sendForgotPasswordEmail = async (email) => {
  try {
    const response = await axios.post(`${API_URL}/forgot-password`, { email }, {
      headers: {
        'Content-Type': 'application/json',
      },
    });
    return response.data;
  } catch (error) {
    handleError(error);
  }
};

// Function to reset the password
export const resetPassword = async (data) => {
  try {
    const response = await axios.post(`${API_URL}/reset-password`, data, {
      headers: {
        'Content-Type': 'application/json',
      },
    });
    return response.data;
  } catch (error) {
    handleError(error);
  }
};
