import React, { useEffect, useState } from 'react';
import { Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { AppBar, Toolbar, Typography, Container, CssBaseline, IconButton, Menu, MenuItem } from '@mui/material';
import AccountCircleIcon from '@mui/icons-material/AccountCircle';
import Sidebar from '../../components/Sidebar/AdminSidebar';
import Subjects from '../../components/Subjects/Subjects';
import AcademicYear from '../../components/AcademicYear/AcademicYear';
import ClassList from '../../components/Classes/ClassList';
import Questionnaires from '../../components/Questionnaires/Questionnaires';
import Dashboard from './Dashboard';
import { fetchDashboardData } from '../../services/admindashbord';
import './AdminDashboard.css';

const AdminDashboard = () => {
  const [dashboardData, setDashboardData] = useState({
    totalFaculties: 0,
    totalStudents: 0,
    totalUsers: 0,
    totalClasses: 0,
    academicYear: '',
    semester: '',
    evaluationStatus: ''
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [anchorEl, setAnchorEl] = useState(null); // Anchor for menu
  const navigate = useNavigate();

  const getDashboardData = async () => {
    try {
      const data = await fetchDashboardData();
      console.log("Fetched Dashboard Data:", data);
      setDashboardData(data);
      setError(null);
    } catch (error) {
      console.error("Error fetching dashboard data:", error);
      setError("Failed to load dashboard data");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    getDashboardData();

    const intervalId = setInterval(() => {
      getDashboardData();
    }, 60000);

    return () => clearInterval(intervalId);
  }, []);

  const handleProfileMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleLogout = () => {
    handleMenuClose();
    navigate('/'); // Redirect to home page on logout
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>;
  }

  return (
    <Container>
      <CssBaseline />
      <AppBar position="fixed">
        <Toolbar>
          <Typography variant="h6" sx={{ flexGrow: 1 }}>
            Admin Dashboard
          </Typography>
          <IconButton color="inherit" onClick={handleProfileMenuOpen}>
            <AccountCircleIcon />
          </IconButton>
          <Menu
            anchorEl={anchorEl}
            open={Boolean(anchorEl)}
            onClose={handleMenuClose}
          >
            <MenuItem onClick={() => { handleMenuClose(); navigate('/profile'); }}>Profile</MenuItem>
            <MenuItem onClick={handleLogout}>Logout</MenuItem>
          </Menu>
        </Toolbar>
      </AppBar>
      <div style={{ display: 'flex', marginTop: '64px' }}>
        <Sidebar />
        <div className="main-content" style={{ flexGrow: 1 }}>
          <Routes>
            <Route 
              path="/" 
              element={
                <Dashboard 
                  totalFaculties={dashboardData.totalFaculties} 
                  totalStudents={dashboardData.totalStudents} 
                  totalUsers={dashboardData.totalUsers} 
                  totalClasses={dashboardData.totalClasses} 
                  academicYear={dashboardData.academicYear} 
                  semester={dashboardData.semester} 
                  evaluationStatus={dashboardData.evaluationStatus} 
                />
              } 
            />
            <Route path="/subjects" element={<Subjects />} />
            <Route path="/academic-year" element={<AcademicYear />} />
            <Route path="/classes" element={<ClassList />} />
            <Route path="/questionnaires" element={<Questionnaires />} />
            <Route path="*" element={<Navigate to="/" />} />
          </Routes>
        </div>
      </div>
    </Container>
  );
};

export default AdminDashboard;
