import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { register } from '../../services/api'; // Import the register function
import { TextField, Radio, RadioGroup, FormControlLabel, Button, Typography, Box, FormHelperText } from '@mui/material';
import { UserPlus } from 'lucide-react'; // Example icon from lucide-react
import './Register.css';

const Register = () => {
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [userType, setUserType] = useState('student'); // Default as 'student'
  const [error, setError] = useState(''); // Error state for validation feedback
  const navigate = useNavigate();

  const handleRegister = async (e) => {
    e.preventDefault();
    setError(''); // Reset error message on form submit

    // Validate password confirmation
    if (password !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }

    // Prepare user data for registration
    const userData = {
      username,
      email,
      mobile,
      password,
      userType,
    };

    try {
      // Send a POST request to the backend API for user registration
      const registeredUser = await register(userData);
      console.log('Registered User:', registeredUser);

      // Navigate to the login page after successful registration
      navigate('/login');
    } catch (error) {
      console.error('Error during registration:', error);
      const errorMessage = error.response?.data || "User Already Exist.";
      setError(errorMessage); // Set the error message from the response
    }
  };

  return (
    <Box className="register-container" sx={{ maxWidth: 400, margin: 'auto', padding: 2 }}>
      <Typography variant="h4" component="h2" align="center" gutterBottom>
        <UserPlus size={32} /> Register
      </Typography>
      {error && <FormHelperText error>{error}</FormHelperText>} {/* Display error message */}
      <form onSubmit={handleRegister}>
        <TextField
          label="Username"
          variant="outlined"
          fullWidth
          margin="normal"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          required
        />
        <TextField
          label="Email"
          type="email"
          variant="outlined"
          fullWidth
          margin="normal"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />
        <TextField
          label="Mobile Number"
          type="tel"
          variant="outlined"
          fullWidth
          margin="normal"
          value={mobile}
          onChange={(e) => setMobile(e.target.value)}
          required
        />
        <TextField
          label="Create Password"
          type="password"
          variant="outlined"
          fullWidth
          margin="normal"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
        <TextField
          label="Confirm Password"
          type="password"
          variant="outlined"
          fullWidth
          margin="normal"
          value={confirmPassword}
          onChange={(e) => setConfirmPassword(e.target.value)}
          required
        />
        
        <RadioGroup row value={userType} onChange={(e) => setUserType(e.target.value)} sx={{ margin: '16px 0' }}>
          <FormControlLabel value="student" control={<Radio />} label="Student" />
          <FormControlLabel value="admin" control={<Radio />} label="Admin" />
          <FormControlLabel value="faculty" control={<Radio />} label="Faculty" />
        </RadioGroup>

        <Button type="submit" variant="contained" color="primary" fullWidth>
          Register
        </Button>
      </form>
    </Box>
  );
};

export default Register;
